const cmds = [
  ["env", `Get-ChildItem Env: | Where-Object { $_.Name -like 'DSH*' } | Format-Table -AutoSize | Out-String -Width 200`],
  ["home", `$h=Join-Path $env:USERPROFILE '.dsh'; Test-Path $h; Get-ChildItem -Force $h -ErrorAction SilentlyContinue | Select-Object Mode,Name | Format-Table -AutoSize | Out-String -Width 200`],
  ["cli", `Get-Command dsh -ErrorAction SilentlyContinue | Format-List Name,Source,Version | Out-String`],
  ["unpacked", `Get-ChildItem -Force 'D:\\Users\\jjq21\\AppData\\Local\\Programs\\DeepSeek Harness\\resources\\app.asar.unpacked' -Recurse -Depth 2 -ErrorAction SilentlyContinue | Select-Object -First 40 FullName | Format-Table -AutoSize | Out-String -Width 250`],
];
const out = await Promise.all(cmds.map(async ([k, c]) => {
  const r = await tools.pwsh({ description: `probe ${k}`, command: c });
  return { k, o: r.kind === "foreground" ? (r.stdout.text + r.stderr.text).trim() : JSON.stringify(r) };
}));
for (const x of out) console.log(`== ${x.k} ==\n${x.o.slice(0, 2500)}`);
